// One item per uploaded resume so each file is converted separately
const out = [];
for (const item of $input.all()) {
  for (const bin of Object.values(item.binary || {})) {
    out.push({ json: { fileName: bin.fileName || 'unknown' }, binary: { data: bin } });
  }
}
if (!out.length) throw new Error('No files uploaded');
return out;

const files = $('Split Files').all();
const MAX_CHARS = 1500;
const out = [];

$input.all().forEach((item, i) => {
  const result = item.json;
  const filename = files[i]?.json.fileName || result.document?.filename || 'unknown';
  if (result.status === 'failure') {
    throw new Error(`Docling failed for ${filename}: ` + JSON.stringify(result.errors));
  }
  const md = result.document?.md_content || '';
  if (!md.trim()) {
    throw new Error(`Docling returned empty content for ${filename} (scanned PDF? enable OCR)`);
  }
  const candidate = filename.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ').trim();

  // Heading-aware sections (Experience, Education, Skills, ...)
  const sections = [];
  let headings = [];
  let text = '';
  for (const line of md.split('\n')) {
    const m = line.match(/^(#{1,3})\s+(.+)/);
    if (m) {
      if (text.trim()) sections.push({ headings: [...headings], text: text.trim() });
      const level = m[1].length;
      headings = headings.slice(0, level - 1);
      headings[level - 1] = m[2];
      text = line + '\n';
    } else {
      text += line + '\n';
    }
  }
  if (text.trim()) sections.push({ headings: [...headings], text: text.trim() });

  for (const sec of sections) {
    const parts = [];
    if (sec.text.length <= MAX_CHARS) {
      parts.push(sec.text);
    } else {
      let chunk = '';
      for (const para of sec.text.split(/\n\n+/)) {
        if (chunk && (chunk + '\n\n' + para).length > MAX_CHARS) {
          parts.push(chunk.trim());
          chunk = para;
        } else {
          chunk = chunk ? chunk + '\n\n' + para : para;
        }
      }
      if (chunk.trim()) parts.push(chunk.trim());
    }
    for (const p of parts) {
      out.push({
        json: {
          // Prefix so every retrieved chunk says whose resume it is
          text: `Candidate: ${candidate} (file: ${filename})\n\n${p}`,
          metadata: { filename, candidate, headings: sec.headings.filter(Boolean) },
        },
      });
    }
  }
});

return out;
